def covered_length(intervals):
    """Return the total length of the union of half-open intervals."""
    spans = sorted((s, e) for s, e in intervals if e > s)
    if not spans:
        return 0

    total = 0
    start, end = spans[0]

    for s, e in spans[1:]:
        if s <= end:
            end = max(end, e)
        else:
            total += end - start
            start, end = s, e

    return total + end - start
