def count_bounded_combinations(coins, target):
    """Return the number of bounded, order-independent coin combinations."""
    if target == 0:
        return 1

    # Merge repeated denominations so identical coins are not distinguished.
    limits = {}
    for value, count in coins:
        if count > 0 and value <= target:
            limits[value] = limits.get(value, 0) + count

    dp = [0] * (target + 1)
    dp[0] = 1

    for value, count in limits.items():
        count = min(count, target // value)
        next_dp = [0] * (target + 1)
        window_width = (count + 1) * value

        # Sliding sums within each residue class modulo value.
        for remainder in range(value):
            window_sum = 0
            for total in range(remainder, target + 1, value):
                window_sum += dp[total]
                if total >= window_width:
                    window_sum -= dp[total - window_width]
                next_dp[total] = window_sum

        dp = next_dp

    return dp[target]
