def eval_expr(s):
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "~": 3}

    def apply_operator():
        op = operators.pop()
        if op == "~":
            values.append(-values.pop())
            return

        right = values.pop()
        left = values.pop()
        if op == "+":
            result = left + right
        elif op == "-":
            result = left - right
        elif op == "*":
            result = left * right
        else:
            result = abs(left) // abs(right)
            if (left < 0) != (right < 0):
                result = -result
        values.append(result)

    i = 0
    expecting_operand = True

    while i < len(s):
        ch = s[i]

        if ch.isspace():
            i += 1
            continue

        if "0" <= ch <= "9":
            number = 0
            while i < len(s) and "0" <= s[i] <= "9":
                number = number * 10 + ord(s[i]) - ord("0")
                i += 1
            values.append(number)
            expecting_operand = False
            continue

        if ch == "(":
            operators.append(ch)
            expecting_operand = True
        elif ch == ")":
            while operators[-1] != "(":
                apply_operator()
            operators.pop()
            expecting_operand = False
        elif ch == "-" and expecting_operand:
            operators.append("~")
        else:
            while (
                operators
                and operators[-1] != "("
                and precedence[operators[-1]] >= precedence[ch]
            ):
                apply_operator()
            operators.append(ch)
            expecting_operand = True

        i += 1

    while operators:
        apply_operator()

    return values[0]
