def cheapest_route(n, edges, src, dst):
    import heapq

    if src == dst:
        return 0

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float("inf")] * n
    dist[src] = 0
    heap = [(0, src)]

    while heap:
        cost, u = heapq.heappop(heap)
        if cost != dist[u]:
            continue
        if u == dst:
            return cost

        for v, w in graph[u]:
            new_cost = cost + w
            if new_cost < dist[v]:
                dist[v] = new_cost
                heapq.heappush(heap, (new_cost, v))

    return -1
