from collections import OrderedDict


def lru_trace(capacity, ops):
    cache = OrderedDict()
    results = []

    for op in ops:
        if op[0] == "put":
            _, key, value = op
            cache[key] = value
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
        else:
            key = op[1]
            if key in cache:
                results.append(cache[key])
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results
