def eval_expr(s: str) -> int:
    precedence = {"+": 1, "-": 1, "*": 2, "@": 2, "^": 3}
    values = []
    operators = []

    def apply_top():
        op = operators.pop()
        b = values.pop()
        a = values.pop()
        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "@":
            values.append(a * b + a + b)
        else:
            values.append(pow(a, b))

    i = 0
    while i < len(s):
        ch = s[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            # Parse directly, avoiding Python's decimal-string digit limit.
            value = 0
            while i < len(s) and "0" <= s[i] <= "9":
                value = value * 10 + ord(s[i]) - ord("0")
                i += 1
            values.append(value)
        elif ch == "(":
            operators.append(ch)
            i += 1
        elif ch == ")":
            while operators[-1] != "(":
                apply_top()
            operators.pop()
            i += 1
        else:
            while operators and operators[-1] != "(":
                top = operators[-1]
                if precedence[top] > precedence[ch] or (
                    precedence[top] == precedence[ch] and ch != "^"
                ):
                    apply_top()
                else:
                    break
            operators.append(ch)
            i += 1

    while operators:
        apply_top()
    return values[0]
