import heapq


def count_shortest_paths(
    n: int, edges: list[tuple[int, int, int]], s: int, t: int
) -> tuple[int, int]:
    MOD = 998244353

    if s == t:
        return (0, 1)

    adj: list[list[tuple[int, int]]] = [[] for _ in range(n)]
    for u, v, w in edges:
        if u != v:
            adj[u].append((v, w))
            adj[v].append((u, w))

    dist: list[int | None] = [None] * n
    count = [0] * n
    dist[s] = 0
    count[s] = 1
    heap = [(0, s)]

    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue

        # Positive weights ensure all shortest-path predecessors
        # have already been processed.
        if u == t:
            return (d, count[u])

        for v, w in adj[u]:
            candidate = d + w
            if dist[v] is None or candidate < dist[v]:
                dist[v] = candidate
                count[v] = count[u]
                heapq.heappush(heap, (candidate, v))
            elif candidate == dist[v]:
                count[v] = (count[v] + count[u]) % MOD

    return (-1, 0)
