def sliding_median_sum(a: list[int], w: int) -> int:
    """Return the sum of window medians in O(n log n) time and O(n) space."""
    if w == 1:
        return sum(a)

    values = sorted(set(a))
    m = len(values)
    index = {value: i + 1 for i, value in enumerate(values)}
    encoded = [index[value] for value in a]

    # Fenwick tree storing the frequency of each value in the window.
    tree = [0] * (m + 1)
    for i in range(w):
        tree[encoded[i]] += 1
    for i in range(1, m + 1):
        parent = i + (i & -i)
        if parent <= m:
            tree[parent] += tree[i]

    highest_bit = 1 << (m.bit_length() - 1)

    def kth(k: int) -> int:
        """Return the value of the k-th smallest element (1-based)."""
        pos = 0
        bit = highest_bit
        while bit:
            nxt = pos + bit
            if nxt <= m and tree[nxt] < k:
                k -= tree[nxt]
                pos = nxt
            bit >>= 1
        return values[pos]

    lower_rank = (w + 1) // 2
    even = w % 2 == 0

    median = kth(lower_rank)
    if even:
        median = (median + kth(lower_rank + 1)) // 2
    total = median

    for right in range(w, len(a)):
        outgoing = encoded[right - w]
        incoming = encoded[right]

        if outgoing != incoming:
            i = outgoing
            while i <= m:
                tree[i] -= 1
                i += i & -i

            i = incoming
            while i <= m:
                tree[i] += 1
                i += i & -i

            median = kth(lower_rank)
            if even:
                median = (median + kth(lower_rank + 1)) // 2

        total += median

    return total
```

