def format_rational(p: int, q: int, d: int) -> str:
    scale = 10 ** d
    kept, remainder = divmod(abs(p) * scale, q)

    twice_remainder = 2 * remainder
    if twice_remainder > q or (twice_remainder == q and kept % 2 == 1):
        kept += 1

    sign = "-" if p < 0 and kept != 0 else ""
    if d == 0:
        return sign + str(kept)

    integer, fractional = divmod(kept, scale)
    return f"{sign}{integer}.{fractional:0{d}d}"
```

