def count_avoiding(n: int, pattern: str, mod: int) -> int:
    m = len(pattern)
    if n < m:
        return pow(2, n, mod)

    # KMP prefix function.
    pi = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j

    # State i means the current suffix matches pattern[:i].
    # Transitions completing the forbidden pattern are discarded.
    matrix = [[0] * m for _ in range(m)]
    for i in range(m):
        for ch in "01":
            j = i
            while j and pattern[j] != ch:
                j = pi[j - 1]
            if pattern[j] == ch:
                j += 1
            if j < m:
                matrix[i][j] += 1

    def square(a):
        result = [[0] * m for _ in range(m)]
        for i, row in enumerate(a):
            out = result[i]
            for k, coefficient in enumerate(row):
                if coefficient:
                    other = a[k]
                    for j in range(m):
                        out[j] += coefficient * other[j]
            for j in range(m):
                out[j] %= mod
        return result

    counts = [0] * m
    counts[0] = 1

    # Binary exponentiation: O(m^3 log n) time, O(m^2) space.
    # Only modular addition and multiplication; mod need not be prime.
    while n:
        if n & 1:
            updated = [0] * m
            for i, coefficient in enumerate(counts):
                if coefficient:
                    row = matrix[i]
                    for j in range(m):
                        updated[j] += coefficient * row[j]
            counts = [value % mod for value in updated]
        n >>= 1
        if n:
            matrix = square(matrix)

    return sum(counts) % mod
