def max_dist_sq(points: list[tuple[int, int]]) -> int:
    pts = sorted(set(points))
    if len(pts) < 2:
        return 0

    def cross(o, a, b):
        return ((a[0] - o[0]) * (b[1] - o[1])
                - (a[1] - o[1]) * (b[0] - o[0]))

    def dist_sq(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    # Strict convex hull: discard intermediate collinear points.
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    hull = lower[:-1] + upper[:-1]
    h = len(hull)
    if h == 2:
        return dist_sq(hull[0], hull[1])

    # Rotating calipers. j advances monotonically through the doubled hull.
    hull += hull
    best = 0
    j = 1

    for i in range(h):
        a = hull[i]
        b = hull[i + 1]
        ex = b[0] - a[0]
        ey = b[1] - a[1]

        while j + 1 < i + h:
            p = hull[j]
            q = hull[j + 1]
            if ex * (q[1] - p[1]) - ey * (q[0] - p[0]) <= 0:
                break
            j += 1

        best = max(best, dist_sq(a, hull[j]), dist_sq(b, hull[j]))

        # Parallel supporting edges can give two tied antipodal vertices.
        if j + 1 < i + h:
            p = hull[j]
            q = hull[j + 1]
            if ex * (q[1] - p[1]) - ey * (q[0] - p[0]) == 0:
                best = max(best, dist_sq(a, q), dist_sq(b, q))

    return best
