def rex_match(pattern: str, s: str) -> bool:
    all_letters = (1 << 26) - 1
    atoms = []
    i = 0

    while i < len(pattern):
        ch = pattern[i]
        if ch == ".":
            mask = all_letters
            i += 1
        elif ch == "[":
            i += 1
            negated = pattern[i] == "^"
            if negated:
                i += 1
            mask = 0
            while pattern[i] != "]":
                mask |= 1 << (ord(pattern[i]) - ord("a"))
                i += 1
            i += 1
            if negated:
                mask = all_letters ^ mask
        else:
            mask = 1 << (ord(ch) - ord("a"))
            i += 1

        quantifier = ""
        if i < len(pattern) and pattern[i] in "?*+":
            quantifier = pattern[i]
            i += 1
        atoms.append((mask, quantifier))

    # dp[j]: processed atoms fully match s[:j].
    # Time: O(len(pattern) + atoms * len(s)); space: O(atoms + len(s)).
    letters = [1 << (ord(ch) - ord("a")) for ch in s]
    n = len(s)
    dp = bytearray(n + 1)
    dp[0] = 1

    for mask, quantifier in atoms:
        current = bytearray(n + 1)

        if quantifier == "*":
            current[0] = dp[0]
            for j, bit in enumerate(letters, 1):
                current[j] = bool(
                    dp[j] or (current[j - 1] and (mask & bit))
                )
        elif quantifier == "+":
            for j, bit in enumerate(letters, 1):
                current[j] = bool(
                    (dp[j - 1] or current[j - 1]) and (mask & bit)
                )
        elif quantifier == "?":
            current[0] = dp[0]
            for j, bit in enumerate(letters, 1):
                current[j] = bool(
                    dp[j] or (dp[j - 1] and (mask & bit))
                )
        else:
            for j, bit in enumerate(letters, 1):
                current[j] = bool(dp[j - 1] and (mask & bit))

        dp = current

    return bool(dp[n])
