def min_edges_to_strongly_connect(n: int, edges: list[tuple[int, int]]) -> int:
    if n == 1:
        return 0

    adj = [[] for _ in range(n)]
    rev = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev[v].append(u)

    # Iterative DFS to obtain vertices in finishing order.
    seen = bytearray(n)
    order = []
    for start in range(n):
        if seen[start]:
            continue
        seen[start] = 1
        stack = [(start, 0)]
        while stack:
            u, i = stack[-1]
            if i == len(adj[u]):
                order.append(u)
                stack.pop()
            else:
                v = adj[u][i]
                stack[-1] = (u, i + 1)
                if not seen[v]:
                    seen[v] = 1
                    stack.append((v, 0))

    # Reverse-graph searches identify strongly connected components.
    component = [-1] * n
    count = 0
    for start in reversed(order):
        if component[start] != -1:
            continue
        component[start] = count
        stack = [start]
        while stack:
            u = stack.pop()
            for v in rev[u]:
                if component[v] == -1:
                    component[v] = count
                    stack.append(v)
        count += 1

    if count == 1:
        return 0

    # In the condensation DAG, the answer is max(sources, sinks).
    has_in = bytearray(count)
    has_out = bytearray(count)
    for u, v in edges:
        cu, cv = component[u], component[v]
        if cu != cv:
            has_out[cu] = 1
            has_in[cv] = 1

    return max(count - sum(has_in), count - sum(has_out))
