def kth_subset_xor(nums: list[int], k: int) -> int:
    basis = [0] * 60
    rank = 0

    # Build a basis indexed by each vector's highest set bit.
    for x in nums:
        while x:
            p = x.bit_length() - 1
            if basis[p]:
                x ^= basis[p]
            else:
                basis[p] = x
                rank += 1
                break
        if rank == 60:
            break

    # Eliminate each pivot bit from all higher-pivot vectors.
    for p in range(60):
        if basis[p]:
            pivot = basis[p]
            mask = 1 << p
            for q in range(p + 1, 60):
                if basis[q] & mask:
                    basis[q] ^= pivot

    # Increasing pivot order maps binary indices to sorted XOR values.
    index = k - 1
    result = 0
    for vector in basis:
        if vector:
            if index & 1:
                result ^= vector
            index >>= 1

    return result
```

