def count_lis(a: list[int]) -> int:
    if not a:
        return 0

    mod = 1_000_000_007
    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    lengths = [0] * (size + 1)
    counts = [0] * (size + 1)

    for value in a:
        rank = ranks[value]

        # Query only smaller values: equal values cannot extend each other.
        i = rank - 1
        best_length = 0
        ways = 0
        while i > 0:
            length = lengths[i]
            if length > best_length:
                best_length = length
                ways = counts[i]
            elif length == best_length:
                ways = (ways + counts[i]) % mod
            i -= i & -i

        if best_length == 0:
            ways = 1
        new_length = best_length + 1

        i = rank
        while i <= size:
            if new_length > lengths[i]:
                lengths[i] = new_length
                counts[i] = ways
            elif new_length == lengths[i]:
                counts[i] = (counts[i] + ways) % mod
            i += i & -i

    best_length = 0
    ways = 0
    i = size
    while i > 0:
        if lengths[i] > best_length:
            best_length = lengths[i]
            ways = counts[i]
        elif lengths[i] == best_length:
            ways = (ways + counts[i]) % mod
        i -= i & -i

    return ways
```

