def tokenize(src: str) -> list[tuple[str, str]]:
    tokens = []
    n = len(src)
    i = 0
    two_ops = {"**", "==", "!=", "<=", ">=", "->"}
    one_ops = set("+-*/%<>=(),:.")

    def is_digit(c: str) -> bool:
        return "0" <= c <= "9"

    def is_id_start(c: str) -> bool:
        return "A" <= c <= "Z" or "a" <= c <= "z" or c == "_"

    while i < n:
        c = src[i]

        if c in " \t\r\n":
            i += 1
            continue

        if c == "#":
            i += 1
            while i < n and src[i] != "\n":
                i += 1
            continue

        start = i

        if c == '"':
            i += 1
            while i < n:
                if src[i] == '"':
                    i += 1
                    tokens.append(("STR", src[start:i]))
                    break
                if src[i] == "\\":
                    if i + 1 >= n:
                        raise ValueError("Unterminated string")
                    if src[i + 1] not in ('"', "\\", "n", "t"):
                        raise ValueError(f"Invalid escape at position {i}")
                    i += 2
                else:
                    i += 1
            else:
                raise ValueError("Unterminated string")
            continue

        if is_digit(c):
            i += 1
            while i < n and is_digit(src[i]):
                i += 1

            if i + 1 < n and src[i] == "." and is_digit(src[i + 1]):
                i += 2
                while i < n and is_digit(src[i]):
                    i += 1

            if i < n and src[i] in "eE":
                j = i + 1
                if j < n and src[j] in "+-":
                    j += 1
                if j < n and is_digit(src[j]):
                    i = j + 1
                    while i < n and is_digit(src[i]):
                        i += 1

            tokens.append(("NUM", src[start:i]))
            continue

        if is_id_start(c):
            i += 1
            while i < n and (is_id_start(src[i]) or is_digit(src[i])):
                i += 1
            tokens.append(("ID", src[start:i]))
            continue

        if src[i:i + 2] in two_ops:
            tokens.append(("OP", src[i:i + 2]))
            i += 2
            continue

        if c in one_ops:
            tokens.append(("OP", c))
            i += 1
            continue

        raise ValueError(f"Unexpected character {c!r} at position {i}")

    return tokens
```

